    def __hash__(self):
        return hash(self.value)
    def __eq__(self, other):
        return isinstance(other, Key) and self.value == other.value
old = Key("a")
new = Key("a")
values = bounded.BoundedTTLSet(2, 5, lambda: now[0])
values.add(old)
values.add("b")
values.add(new)
values.add("c")
assert list(values._entries)[0] is new
assert "b" not in values
old_ref = weakref.ref(old)
del old
gc.collect()
assert old_ref() is None
now[0] = 10
values = bounded.BoundedTTLSet(2, 5, lambda: now[0])
values.add("head")
now[0] = 0
values.add("tail")
now[0] = 5
assert "tail" not in values and "head" in values
for args in [(True, 1, lambda: 0), (0, 1, lambda: 0)]:
    try:
        bounded.BoundedTTLSet(*args)
    except (TypeError, ValueError):
        pass
    else:
        raise AssertionError
for ttl in [True, float("nan"), float("inf"), -1]:
    try:
        bounded.BoundedTTLSet(1, ttl, lambda: 0)
    except (TypeError, ValueError):
        pass
    else:
        raise AssertionError

 duration = load("duration")
assert duration.parse_duration("2d3h4m5s6ms") == {"days": 2, "hours": 3, "minutes": 4, "seconds": 5, "milliseconds": 6}
assert duration.normalize_duration("1h60m") == "2h"
assert duration.normalize_duration("1h120m3601s1001ms") == "4h2s1ms"
for text, expected in [(None, ("type", 0)), ("", ("empty", 0)), ("01s", ("leading_zero", 0)), ("1h 2m", ("syntax", 2)), ("1ms2s", ("order", 4)), ("24h", ("range", 0)), ("1.5s", ("syntax", 1)), ("1s1s", ("order", 3)), ("1s2", ("syntax", 3))]:
    try:
        duration.parse_duration(text)
    except duration.DurationParseError as error:
        assert (error.code, error.position) == expected
    else:
        raise AssertionError(text)
for text in ["1d", "1h", "1m", "1s", "1ms", "24h", "0d0h0m0s0ms", "1h120m3601s1001ms"]:
    normalized = duration.normalize_duration(text)
    assert duration.normalize_duration(normalized) == normalized
